import {CHOICES,ARTIFACTS,SCENES} from '../model.mjs';
import {createChoiceGroup} from './choice-group.mjs';
const $=id=>document.getElementById(id);
const announce=text=>$('system-announcement').textContent=text;
const reducedMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
let previewChoice=null,componentChoice=null,currentArtifact='boxes',revealAnimation=null;
const stageImage=$('stage-photo');
function stageImageState(error=false){const status=$('stage-media-state');status.hidden=stageImage.complete&&stageImage.naturalWidth>0&&!error;$('stage-media-message').textContent=error?'The artifact photograph could not load.':'Loading the artifacts…';$('retry-stage-photo').hidden=!error;}
stageImage.addEventListener('load',()=>stageImageState());stageImage.addEventListener('error',()=>stageImageState(true));$('retry-stage-photo').addEventListener('click',()=>{stageImage.src='assets/boxes-closed.webp';stageImageState();});stageImageState(stageImage.complete&&!stageImage.naturalWidth);
function reveal(element){if(reducedMotion()||!element.animate)return;revealAnimation?.cancel();revealAnimation=element.animate([{clipPath:'inset(0 0 100% 0)',opacity:.5},{clipPath:'inset(0 0 0 0)',opacity:1}],{duration:parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--dna-time-reveal'))||360,easing:getComputedStyle(document.documentElement).getPropertyValue('--dna-ease-out').trim()||'ease-out'});}
function chooseOpening(choice){if(!CHOICES.some(c=>c.id===choice))throw new Error('Unknown choice');const first=previewChoice===null;previewChoice=choice;opening.set(choice);renderMatrix();$('opening-answer').textContent=CHOICES.find(c=>c.id===choice).label;$('opening-reflection').hidden=false;if(first)reveal($('opening-reflection'));announce(`${$('opening-answer').textContent}. What would you want those extra years to hold?`);return {choice,reflection:'What would you want those extra years to hold?'};}
const opening=createChoiceGroup($('opening-choices'),{name:'opening-answer',legend:'Your answer to the fictional offer',onChange:chooseOpening});
$('clear-preview').addEventListener('click',()=>{previewChoice=null;opening.set(null);renderMatrix();$('opening-reflection').hidden=true;$('opening-answer').textContent='';revealAnimation?.cancel();announce('The opening preview answer is cleared.');document.querySelector('#opening-choices input').focus();});
const components=createChoiceGroup($('component-choices'),{name:'component-answer',legend:'Decision component preview',onChange(choice){componentChoice=choice;$('component-feedback').textContent=`Selected: ${CHOICES.find(c=>c.id===choice).label}.`;$('choice-state').value='selected';}});
$('choice-state').addEventListener('change',()=>{const state=$('choice-state').value;components.disable(state==='disabled');if(state==='ready'){componentChoice=null;components.set(null);$('component-feedback').textContent='No preview answer selected.';}else if(state==='selected'){componentChoice??='extend';components.set(componentChoice);$('component-feedback').textContent=`Selected: ${CHOICES.find(c=>c.id===componentChoice).label}.`;}else $('component-feedback').textContent='Unavailable state preview. These controls are disabled.';});
const tokens=[['Wall','--dna-wall'],['Sheet','--dna-sheet'],['Ink','--dna-ink'],['Secondary','--dna-muted'],['Life','--dna-life'],['Mortality','--dna-end'],['Focus','--dna-focus']];
for(const [name,token] of tokens){const value=getComputedStyle(document.documentElement).getPropertyValue(token).trim(),button=document.createElement('button');button.className='swatch';button.style.setProperty('--swatch-color',value);button.setAttribute('aria-label',`Copy ${name} CSS token, ${value}`);button.innerHTML=`<span class="swatch__color" aria-hidden="true"></span><span class="swatch__name">${name}</span><span class="swatch__value">${value.toUpperCase()}</span>`;button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(`${token}: ${value};`);announce(`Copied ${token}: ${value}.`);button.querySelector('.swatch__value').textContent='Copied';setTimeout(()=>button.querySelector('.swatch__value').textContent=value.toUpperCase(),1600);}catch{announce(`Copy unavailable. Token value: ${token}: ${value}.`);button.querySelector('.swatch__value').textContent=`${token}: ${value}`;}});$('palette').append(button);}
for(const [pixels,token] of [[16,'--dna-space-4'],[24,'--dna-space-6'],[40,'--dna-space-10'],[64,'--dna-space-16'],[96,'--dna-space-24']]){const item=document.createElement('div');item.className='spacing-step';item.style.setProperty('--ruler-size',`var(${token})`);item.innerHTML=`<div aria-hidden="true"></div><span>${pixels}px</span><code>${token}</code>`;$('spacing-ruler').append(item);}
$('replay-reflection').addEventListener('click',()=>{reveal($('motion-reflection'));announce(reducedMotion()?'Reflection visible. Reduced motion is enabled.':'Reflection reveal replayed.');});
$('read-motion').addEventListener('click',()=>{const rule=$('motion-rule');rule.hidden=!rule.hidden;$('read-motion').setAttribute('aria-expanded',String(!rule.hidden));});$('read-motion').setAttribute('aria-expanded','false');$('read-motion').setAttribute('aria-controls','motion-rule');
function mediaState(state){const content=$('media-state-content'),img=$('state-image');$('media-state').value=state;img.hidden=state!=='ready';content.hidden=state==='ready';$('media-demo').setAttribute('aria-busy',String(state==='loading'));if(state==='loading'){content.innerHTML='<div class="state-progress" aria-hidden="true"></div><h3>Loading photograph…</h3><p>Loading state preview</p>';}else if(state==='error'){content.innerHTML='<h3>Photograph couldn’t load.</h3><p>Error state preview. Use the recovery action below.</p><button class="dna-button dna-button--quiet" id="retry-image">Retry photograph</button>';$('retry-image').addEventListener('click',()=>{mediaState('loading');img.src='assets/pill-pack.webp';});}else content.replaceChildren();}
$('media-state').addEventListener('change',()=>mediaState($('media-state').value));$('state-image').addEventListener('load',()=>{if($('media-state').value==='loading')mediaState('ready');});$('state-image').addEventListener('error',()=>mediaState('error'));
for(const scene of SCENES){const option=document.createElement('option');option.value=scene.id;option.textContent=scene.short;$('scene-preview').append(option);}
function scenePreview(id){const index=SCENES.findIndex(s=>s.id===id),scene=SCENES[index];if(!scene)throw new Error('Unknown situation');$('progress-preview').innerHTML=`<div class="dna-progress" role="img" aria-label="Situation ${index+1} of 6, ${scene.short}"><div class="dna-progress__bars" aria-hidden="true">${SCENES.map((_,i)=>`<span data-current="${i===index}"></span>`).join('')}</div><span class="dna-progress__label">${index+1} / 6</span></div>`;$('condition-preview-title').textContent=scene.title.replace('\n',' ');$('condition-preview-text').textContent=scene.condition;}
$('scene-preview').addEventListener('change',()=>scenePreview($('scene-preview').value));scenePreview('offer');
const tabs=ARTIFACTS.map((artifact,index)=>{const tab=document.createElement('button');tab.type='button';tab.id=`system-tab-${artifact.id}`;tab.dataset.artifact=artifact.id;tab.setAttribute('role','tab');tab.setAttribute('aria-controls','system-artifact-panel');tab.textContent=artifact.title;tab.addEventListener('click',()=>selectArtifact(artifact.id));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%ARTIFACTS.length;else if(event.key==='ArrowLeft')next=(index+ARTIFACTS.length-1)%ARTIFACTS.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=ARTIFACTS.length-1;else return;event.preventDefault();selectArtifact(ARTIFACTS[next].id);tabs[next].focus();});$('system-artifact-tabs').append(tab);return tab;});
function selectArtifact(id){const artifact=ARTIFACTS.find(a=>a.id===id);if(!artifact)throw new Error('Unknown artifact');currentArtifact=id;for(const tab of tabs){const selected=tab.dataset.artifact===id;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;}$('system-artifact-panel').setAttribute('aria-labelledby',`system-tab-${id}`);$('inspection-title').textContent=artifact.title;$('inspection-copy').textContent=artifact.text;const img=$('inspection-image');$('inspection-status').hidden=false;$('inspection-status').textContent='Loading photograph…';$('inspection-image').alt=artifact.alt;img.src=`assets/${artifact.file}`;if(img.complete&&img.naturalWidth)$('inspection-status').hidden=true;return {artifact:id,title:artifact.title};}
$('inspection-image').addEventListener('load',()=>{$('inspection-status').hidden=true;$('inspection-status').replaceChildren();});$('inspection-image').addEventListener('error',()=>{const status=$('inspection-status');status.hidden=false;status.replaceChildren();const button=document.createElement('button');button.className='dna-button dna-button--quiet';button.textContent='Photograph unavailable. Retry';button.addEventListener('click',()=>selectArtifact(currentArtifact));status.append(button);});
function inspect(id=currentArtifact){const result=selectArtifact(id);if(!$('artifact-sheet').open)$('artifact-sheet').showModal();return result;}
$('inspect-artifacts').addEventListener('click',()=>inspect());$('inspect-again').addEventListener('click',()=>inspect());$('close-sheet').addEventListener('click',()=>$('artifact-sheet').close());$('artifact-sheet').addEventListener('click',event=>{if(event.target!==$('artifact-sheet'))return;const r=$('artifact-sheet').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('artifact-sheet').close();});
selectArtifact('boxes');
// Page-scoped preview actions do not submit responses or expose private notes.
if(document.modelContext?.registerTool){const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{/* The native interface works without this optional capability. */}};
 register({name:'select_system_preview_choice',title:'Try a decision component',description:'Choose a response in the fictional opening preview. Stored only in page memory.',inputSchema:{type:'object',properties:{choice:{type:'string',enum:CHOICES.map(c=>c.id)}},required:['choice'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='choice'))throw new Error('Expected one choice');return chooseOpening(input.choice);}});
 register({name:'inspect_system_artifact',title:'Inspect an original artifact',description:'Open the original artifact photograph in the system’s inspection sheet.',inputSchema:{type:'object',properties:{artifact:{type:'string',enum:ARTIFACTS.map(a=>a.id)}},required:['artifact'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='artifact'))throw new Error('Expected an artifact');return inspect(input.artifact);}});
}

function renderMatrix(){
 $('preview-matrix').innerHTML=SCENES.map((scene,index)=>`<tr><td>${index===0?'<button class="dna-matrix__revise" id="revise-opening">The original offer</button>':scene.short}</td>${CHOICES.map(choice=>`<td>${index===0&&previewChoice===choice.id?`<span class="dna-matrix__selected" role="img" aria-label="${choice.short} selected"><svg class="dna-icon" aria-hidden="true"><use href="#icon-check"/></svg></span>`:'<span class="dna-matrix__empty" aria-label="Not selected">·</span>'}</td>`).join('')}<td>${index===0&&previewChoice?'Initial':'Not answered'}</td></tr>`).join('');
 $('revise-opening').addEventListener('click',()=>{document.querySelector('#opening-choices input').focus();document.querySelector('#opening-choices').scrollIntoView({block:'center'});});
}
$('system-note').addEventListener('input',()=>{$('system-note').value=$('system-note').value.slice(0,500);$('system-note-count').textContent=`${$('system-note').value.length} / 500`;});
$('clear-system-note').addEventListener('click',()=>{$('system-note').value='';$('system-note-count').textContent='0 / 500';$('system-note').focus();announce('Your preview note is cleared.');});
renderMatrix();
